What will be logged to the console and displayed in the DOM after the button is clicked once?

function Counter() {
  const [count, setCount] = React.useState(0);
  const handleClick = () => {
    setCount(count + 1);
    setCount((prev) => prev + 2);
    setCount(count + 1);
    console.log(count);
  };
  return <button onClick={handleClick}>{count}</button>;
}

